INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,BroadcastTextId,TextRange,comment) SELECT 38537,0,0,'My Lady!  Should I order my men to stop the deployment of the Plague?  Or are we to continue as planned?',12,0,100,66,0,0,38440,0,'High Executor Crenshaw to Player' WHERE EXISTS (SELECT 1 FROM creature_template WHERE entry=38537 AND AIName='') AND NOT EXISTS (SELECT 1 FROM creature_text WHERE CreatureID=38537 AND GroupID=0 AND ID=0);
UPDATE creature_text SET BroadcastTextId=38440,Sound=CASE WHEN Sound=19606 THEN 0 ELSE Sound END WHERE CreatureID=38537 AND GroupID=0 AND ID=0 AND Text='My Lady!  Should I order my men to stop the deployment of the Plague?  Or are we to continue as planned?' AND BroadcastTextId IN (0,38440) AND EXISTS (SELECT 1 FROM creature_template WHERE entry=38537 AND AIName='');
